// The obligation to change a generated password (MH-07). When the staff makes an account for a hiker,
// the first password is generated by the server and sent by email. Until the hiker chooses a new one,
// nothing else works: the user can only see who they are, change the password or log out.
import { ForbiddenError } from './errors.js';

// Throws ForbiddenError (403) with the code PASSWORD_CHANGE_REQUIRED while the user must still change
// the password. Called for every request except the three above.
export const requirePasswordChanged = (user) => {
  if (user.mustChangePassword) {
    throw new ForbiddenError('You must change your password first', { code: 'PASSWORD_CHANGE_REQUIRED' });
  }
};
